export const points = [[37,37],[128,29],[225,43],[322,32],[55,119],[144,109],[232,132],[312,118],[34,211],[123,202],[215,216],[326,208],[54,294],[149,283],[237,302],[312,289],[32,365],[127,369],[219,355],[326,369]].map(([x,y],id)=>({x,y,id}));
export const key=(a,b)=>[a,b].sort((x,y)=>x-y).join('-');
const cross=(a,b,c)=>(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);
const between=(a,b,c)=>Math.abs(cross(a,b,c))<.001&&c.x>=Math.min(a.x,b.x)&&c.x<=Math.max(a.x,b.x)&&c.y>=Math.min(a.y,b.y)&&c.y<=Math.max(a.y,b.y);
export function valid(a,b,edges){if(!Number.isInteger(a)||!Number.isInteger(b)||!points[a]||!points[b]||a===b||edges.has(key(a,b)))return false;const p=points[a],q=points[b];if(points.some(r=>r.id!==a&&r.id!==b&&between(p,q,r)))return false;for(const e of edges.values()){if([e.a,e.b].includes(a)||[e.a,e.b].includes(b))continue;const r=points[e.a],s=points[e.b];if(cross(p,q,r)*cross(p,q,s)<=0&&cross(r,s,p)*cross(r,s,q)<=0)return false}return true}
export function moves(edges){let n=0;for(let a=0;a<points.length;a++)for(let b=a+1;b<points.length;b++)if(valid(a,b,edges))n++;return n}
export function triangles(a,b,edges,claimed){return points.filter(p=>p.id!==a&&p.id!==b).map(p=>[a,b,p.id].sort((x,y)=>x-y)).filter(ids=>{const [i,j,k]=ids;if(claimed.has(ids.join('-'))||!edges.has(key(i,k))||!edges.has(key(j,k))||!edges.has(key(i,j)))return false;const [p,q,r]=ids.map(i=>points[i]);if(Math.abs(cross(p,q,r))<.001)return false;return !points.some(s=>{if(ids.includes(s.id))return false;const c=[cross(p,q,s),cross(q,r,s),cross(r,p,s)];return c.every(n=>n>=0)||c.every(n=>n<=0)})})}
